package goxmap

import (
	"fmt"
	"sort"
)

// MappingKind describes how precisely generated bytes correspond to source.
type MappingKind uint8

const (
	// Exact maps byte-for-byte preserved text. Generated and original ranges
	// must have the same length.
	Exact MappingKind = iota
	// Anchor associates generated scaffolding with an original range. Positions
	// inside it resolve to the start of the original range and are not exact.
	Anchor
)

// SourceRange identifies a range in one source document.
type SourceRange struct {
	URI   string
	Range Range
}

// Mapping relates one range in a generated document to an original source.
type Mapping struct {
	Generated Range
	Original  SourceRange
	Kind      MappingKind
}

// Position is the result of a source-map lookup.
type Position struct {
	URI    string
	Offset int
	Exact  bool
}

// Map is an immutable, bidirectional source map. Generated ranges may not
// overlap, which keeps forward lookups deterministic. Multiple generated
// ranges may refer to the same original range.
type Map struct {
	generatedURI string
	mappings     []Mapping
}

// New validates and constructs a source map. Input mappings are copied and
// sorted by their generated range.
func New(generatedURI string, mappings []Mapping) (*Map, error) {
	if generatedURI == "" {
		return nil, fmt.Errorf("generated URI cannot be empty")
	}
	items := append([]Mapping(nil), mappings...)
	for index, mapping := range items {
		if !mapping.Generated.Valid() || mapping.Generated.Empty() {
			return nil, fmt.Errorf("mapping %d has invalid or empty generated range", index)
		}
		if mapping.Original.URI == "" {
			return nil, fmt.Errorf("mapping %d has an empty original URI", index)
		}
		if !mapping.Original.Range.Valid() {
			return nil, fmt.Errorf("mapping %d has an invalid original range", index)
		}
		switch mapping.Kind {
		case Exact:
			if mapping.Generated.Len() != mapping.Original.Range.Len() {
				return nil, fmt.Errorf("exact mapping %d has generated length %d and original length %d", index, mapping.Generated.Len(), mapping.Original.Range.Len())
			}
		case Anchor:
		default:
			return nil, fmt.Errorf("mapping %d has unknown kind %d", index, mapping.Kind)
		}
	}
	sort.SliceStable(items, func(a, b int) bool {
		return items[a].Generated.Start < items[b].Generated.Start
	})
	for index := 1; index < len(items); index++ {
		if items[index-1].Generated.End > items[index].Generated.Start {
			return nil, fmt.Errorf("generated ranges %v and %v overlap", items[index-1].Generated, items[index].Generated)
		}
	}
	return &Map{generatedURI: generatedURI, mappings: items}, nil
}

// GeneratedURI returns the identity of the generated document.
func (m *Map) GeneratedURI() string {
	return m.generatedURI
}

// Mappings returns a copy of the map's ordered segments.
func (m *Map) Mappings() []Mapping {
	return append([]Mapping(nil), m.mappings...)
}

// OriginalPosition maps a generated byte offset back to its GOX source.
func (m *Map) OriginalPosition(offset int) (Position, bool) {
	mapping, ok := m.mappingAt(offset)
	if !ok {
		return Position{}, false
	}
	position := Position{URI: mapping.Original.URI, Offset: mapping.Original.Range.Start}
	if mapping.Kind == Exact {
		position.Offset += offset - mapping.Generated.Start
		position.Exact = true
	}
	return position, true
}

// OriginalRange maps a non-empty generated range when it is fully contained
// in one mapping segment. Ranges crossing generated and source boundaries are
// intentionally rejected instead of being reported with false precision.
func (m *Map) OriginalRange(generated Range) (SourceRange, MappingKind, bool) {
	if !generated.Valid() || generated.Empty() {
		return SourceRange{}, Exact, false
	}
	mapping, ok := m.mappingAt(generated.Start)
	if !ok || generated.End > mapping.Generated.End {
		return SourceRange{}, Exact, false
	}
	if mapping.Kind == Anchor {
		return mapping.Original, Anchor, true
	}
	start := mapping.Original.Range.Start + generated.Start - mapping.Generated.Start
	return SourceRange{
		URI:   mapping.Original.URI,
		Range: Range{Start: start, End: start + generated.Len()},
	}, Exact, true
}

func (m *Map) mappingAt(offset int) (Mapping, bool) {
	index := sort.Search(len(m.mappings), func(index int) bool {
		return m.mappings[index].Generated.End > offset
	})
	if index == len(m.mappings) || !m.mappings[index].Generated.Contains(offset) {
		return Mapping{}, false
	}
	return m.mappings[index], true
}

// GeneratedPositions maps an original byte offset to every generated location
// derived from it. Results follow generated-document order.
func (m *Map) GeneratedPositions(uri string, offset int) []Position {
	var positions []Position
	for _, mapping := range m.mappings {
		if mapping.Original.URI != uri || !mapping.Original.Range.Contains(offset) {
			continue
		}
		position := Position{URI: m.generatedURI, Offset: mapping.Generated.Start}
		if mapping.Kind == Exact {
			position.Offset += offset - mapping.Original.Range.Start
			position.Exact = true
		}
		positions = append(positions, position)
	}
	return positions
}

// Compose combines lower (generated -> intermediate) with upper
// (intermediate -> original). Only lower ranges that refer to upper's generated
// URI participate. Exact intersections stay exact; generated scaffolding or an
// upstream anchor remains an anchor.
func Compose(generatedURI string, lower, upper *Map) (*Map, error) {
	if lower == nil || upper == nil {
		return nil, fmt.Errorf("source maps to compose cannot be nil")
	}
	if generatedURI == "" || generatedURI != lower.generatedURI {
		return nil, fmt.Errorf("composed URI %q does not match lower generated URI %q", generatedURI, lower.generatedURI)
	}
	var composed []Mapping
	for _, low := range lower.mappings {
		if low.Original.URI != upper.generatedURI {
			continue
		}
		for _, high := range upper.mappings {
			start := max(low.Original.Range.Start, high.Generated.Start)
			end := min(low.Original.Range.End, high.Generated.End)
			if start >= end {
				continue
			}

			if low.Kind == Exact && high.Kind == Exact {
				generatedStart := low.Generated.Start + start - low.Original.Range.Start
				originalStart := high.Original.Range.Start + start - high.Generated.Start
				length := end - start
				composed = append(composed, Mapping{
					Generated: Range{Start: generatedStart, End: generatedStart + length},
					Original:  SourceRange{URI: high.Original.URI, Range: Range{Start: originalStart, End: originalStart + length}},
					Kind:      Exact,
				})
				continue
			}

			generated := low.Generated
			if low.Kind == Exact {
				generated.Start += start - low.Original.Range.Start
				generated.End = generated.Start + end - start
			}
			original := high.Original
			if high.Kind == Exact {
				originalStart := high.Original.Range.Start + start - high.Generated.Start
				original.Range = Range{Start: originalStart, End: originalStart + end - start}
			}
			composed = append(composed, Mapping{
				Generated: generated,
				Original:  original,
				Kind:      Anchor,
			})
			// An anchor covers its complete generated range and must remain one
			// deterministic segment even if several upper ranges intersect it.
			if low.Kind == Anchor {
				break
			}
		}
	}
	return New(generatedURI, composed)
}
